    @Test
    void submitApproveAndCapacityAccounting() throws Exception {
        long windowId = createWindow("ch-flow-" + run,
                "2026-10-04T00:00:00Z", "2026-10-04T02:00:00Z", "1.000");
        String a1 = submitAllocation(windowId, "user-1", "0.4", "alice");
