        for (Future<Integer> future : futures) {
            int status = future.get(30, TimeUnit.SECONDS);
            if (status == 200) {
                ok++;
            } else if (status == 422) {
                quota++;
            }
        }
        pool.shutdown();
        assertEquals(5, ok, "恰好 5 个 0.2 可以放入 1.000");
        assertEquals(5, quota);
