        // 操作人不是源申请人 -> 409
        postJson("/api/transfers", transferBody(key("tkc"), key("tk"), source, otherUser), "bob", 409);
        // 源/目标不存在 -> 404
        postJson("/api/transfers", transferBody(key("tkc"), key("tk"), "missing-" + run, otherUser),
                "alice", 404);
