@AutoConfigureMockMvc
class SettlementApiTests {
    @Autowired MockMvc mvc;
    @Autowired ObjectMapper objectMapper;
    @Autowired WaterService waterService;

    private final String run = UUID.randomUUID().toString().substring(8);
    private int seq;
    private String key(String prefix) { return prefix + "-" + run + "-" + (++seq); }

    // helpers: postJson, postOk, getOk, createWindow, submit, approve, transfer, settle, reconcile...

    @Test void settlementBillsPerFarmerWithTieredRates() ...
    @Test void halfUpRoundingToCents() ...
    @Test void syntheticScenarioMatchesExpectedAmounts() ... // 350 -> 290/-60 -> 260/-30
    @Test void zeroChangeReconcileSavesZeroDiffVersion() ...
    @Test void reconcileValidatesExpectedVersion() ...
    @Test void settlementLifecycleErrors() ... // settle twice 409, reconcile before settle 404, current 404, missing window 404
    @Test void cancelProducesNegativeDiffAndKeepsOldVersions() ...
    @Test void sameRequestIdReplaysAndDifferentParamsConflict() ...
    @Test void failedReconcileDoesNotOccupyRequestId() ...
    @Test void concurrentReconcilesAdvanceVersionOnlyOnce() ...
    @Test void reconcileAndTransferSerializeOnWindowLock() ...
    @Test void invalidFarmerTotalReturns422() ... // static billFarmer checks
}
