        assertEquals(r1, r1Replay);
        assertEquals(2, getOk("/api/windows/" + windowId + "/settlements").get("settlements").size());
        // 同键改参（期望版本不同）-> 409
        reconcile(windowId, reconcileId, 2, 409);
